import { BaseHandler } from "../response/base.js";
import { joinPath } from "../../../utils/path-utils.js";
import { HTTP_OK, HTTP_UNAVAILABLE, PRIORITY_HIGH } from "../../../utils/constants/index.js";
import { isTracingDegraded, isTracingEnabled } from "../../../observability/index.js";
import { RUNTIME_VERSION } from "../../../utils/version.js";
import { DEPENDENCY_ARTIFACT_BUILD_CAPABILITY } from "../../../release-assets/dependency-artifact-contracts.js";
let serverInitialized = false;
export function setServerInitialized(ready) {
    serverInitialized = ready;
}
export function isServerInitialized() {
    return serverInitialized;
}
export class HealthHandler extends BaseHandler {
    metadata = {
        name: "HealthHandler",
        priority: PRIORITY_HIGH,
        patterns: [
            { pattern: "/healthz", exact: true },
            { pattern: "/readyz", exact: true },
            { pattern: "/_health", exact: true },
        ],
    };
    async checkReadiness(ctx) {
        if (!serverInitialized || !ctx.adapter)
            return false;
        try {
            if (ctx.config?.fs?.veryfront?.proxyMode === true)
                return true;
            const projectDirStat = await ctx.adapter.fs.stat(ctx.projectDir);
            return !!projectDirStat?.isDirectory;
        }
        catch (_) {
            /* expected: project directory may not exist */
            return false;
        }
    }
    async handle(req, ctx) {
        if (!this.shouldHandle(req, ctx))
            return this.continue();
        const pathname = new URL(req.url).pathname;
        const builder = this.createResponseBuilder(ctx)
            .withCORS(req, ctx.securityConfig?.cors)
            .withSecurity(ctx.securityConfig ?? undefined, req);
        if (pathname === "/healthz") {
            return this.respond(builder.json({ service: "veryfront-server", status: "ok" }, HTTP_OK));
        }
        if (pathname === "/readyz") {
            const isReady = await this.checkReadiness(ctx);
            return this.respond(builder.text(isReady ? "ready" : "not-ready", isReady ? HTTP_OK : HTTP_UNAVAILABLE));
        }
        if (pathname !== "/_health")
            return this.continue();
        const hasStaticBuild = await this.hasDistDirectory(ctx);
        const tracingDegraded = isTracingDegraded();
        return this.respond(builder.withCache("no-cache").json({
            service: "veryfront-server",
            status: tracingDegraded ? "degraded" : "ok",
            timestamp: new Date().toISOString(),
            mode: hasStaticBuild ? "static+ssr" : "ssr",
            version: RUNTIME_VERSION,
            capabilities: [DEPENDENCY_ARTIFACT_BUILD_CAPABILITY],
            tracing: {
                enabled: isTracingEnabled(),
                degraded: tracingDegraded,
            },
        }, HTTP_OK));
    }
    async hasDistDirectory(ctx) {
        try {
            const st = await ctx.adapter.fs.stat(joinPath(ctx.projectDir, "dist"));
            return !!st?.isDirectory;
        }
        catch (_) {
            /* expected: dist directory may not exist */
            return false;
        }
    }
}
